-- kate-plusplus · Notepad overlay for Caelestia (Hyprland Lua config)
-- Installed to ~/.config/kate-plusplus/hyprland.lua and loaded from
-- ~/.config/caelestia/hypr-user.lua. Generated by `kate-plusplus install`;
-- change the key with `kate-plusplus install --hotkey "SUPER + X"`.

local hotkey = "@HOTKEY@"

-- The scratchpad Kate runs with its own app id, so only it lands here —
-- normal Kate windows stay wherever you open them.
hl.window_rule({
    match     = { class = "kate-scratchpad" },
    workspace = "special:notepad",
    float     = true,
    size      = "(monitor_w*0.52) (monitor_h*0.66)",
    center    = true,
})

-- Same toggle as SUPER + D (communication): first press opens/starts it,
-- second press hides it. App definition lives in ~/.config/caelestia/cli.json.
local ok, fn = pcall(require, "utils.functions")
if ok and fn.toggle then
    hl.bind(hotkey, fn.toggle("notepad"))
end
